if (uri.getQuery() != null) {
    // Extract the raw query string directly from the URL to avoid Android's Uri
    // class which decodes percent-encoded characters. This is critical because
    // UrlQuerySanitizer splits on literal '&' first, then decodes values — so a
    // percent-encoded '&' (%26) must remain encoded during the split phase.
    var urlString = urlData.url;
    var queryStart = urlString.indexOf('?');
    if (queryStart >= 0) {
        var fragStart = urlString.indexOf('#', queryStart + 1);
        if (fragStart >= 0) {
            rawQuery = urlString.substring(queryStart + 1, fragStart);
        } else {
            rawQuery = urlString.substring(queryStart + 1);
        }
    }
    if (rawQuery != null) {
        urlQuerySanitizer.setAllowUnregisteredParamaters(true);
        urlQuerySanitizer.setUnregisteredParameterValueSanitizer(v -> v);
        urlQuerySanitizer.parseQuery(rawQuery);
    }
}

